1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"fmt"
17		"sort"
18	)
19	
20	// SnapshotFormatVersion is the only on-disk snapshot format understood.
21	const SnapshotFormatVersion = 1
22	
23	// SnapshotFile is the on-disk representation of one frozen lineage graph.
24	//
25	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
26	// verified against Graph on every read; Graph carries the complete graph.
27	type SnapshotFile struct {
28		FormatVersion int       `json:"formatVersion"`
29		ContentID     string    `json:"contentId"`
30		Graph         GraphFile `json:"graph"`
31	}
32	
33	// RootSourceChange reports that one dataset present in BOTH versions reaches a
34	// different set of root sources. OldRoots and NewRoots are sorted by name and
35	// never nil, so empty root sets encode as [] rather than null.
36	type RootSourceChange struct {
37		Dataset  string   `json:"dataset"`
38		OldRoots []string `json:"oldRoots"`
39		NewRoots []string `json:"newRoots"`
40	}
41	
42	// CompareReport is the deterministic, read-only diff of two snapshots read in
43	// the fixed direction old -> new.
44	//
45	// NewDatasets and RemovedDatasets list nodes present on only one side.
46	// ChangedDatasets lists datasets present on both sides whose direct upstream
47	// set actually changed. AddedRelations and RemovedRelations list every
48	// directed edge present on only one side, including edges that vanish because
49	// one endpoint node was removed. RootSourceChanges covers only datasets common
50	// to both versions whose reachable root set differs; added or removed datasets
51	// never appear there.
52	type CompareReport struct {
53		NewDatasets       []string           `json:"newDatasets"`
54		RemovedDatasets   []string           `json:"removedDatasets"`
55		ChangedDatasets   []string           `json:"changedDatasets"`
56		AddedRelations    []Relation         `json:"addedRelations"`
57		RemovedRelations  []Relation         `json:"removedRelations"`
58		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
59	}
60	
61	// contentIDPrefix names the hash algorithm used for content addressing.
62	const contentIDPrefix = "sha256:"
63	
64	// canonicalGraph serializes the graph's semantics deterministically: datasets
65	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
66	// JSON with no insignificant whitespace. Two semantically equal graphs always
67	// produce identical bytes.
68	func canonicalGraph(adj adjacency) ([]byte, error) {
69		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
70		return json.Marshal(gf)
71	}
72	
73	// computeContentID returns the content identifier of the graph bytes:
74	// "sha256:" followed by the lowercase hex SHA-256 digest.
75	func computeContentID(canonical []byte) string {
76		sum := sha256.Sum256(canonical)
77		return contentIDPrefix + hex.EncodeToString(sum[:])
78	}
79	
80	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
81	// version 1 and the matching content identifier. It does not mutate graph. The
82	// returned document and its serialized bytes depend only on graph semantics.
83	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
84		if err := ValidateGraph(graph); err != nil {
85			return nil, err
86		}
87		adj, err := graphAdjacency(graph)
88		if err != nil {
89			return nil, err
90		}
91		canonical, err := canonicalGraph(adj)
92		if err != nil {
93			return nil, err
94		}
95		return &SnapshotFile{
96			FormatVersion: SnapshotFormatVersion,
97			ContentID:     computeContentID(canonical),
98			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
99		}, nil
100	}
101	
102	// MarshalSnapshot serializes a snapshot the same way for every save: indented
103	// JSON keyed by struct field order, terminated by a single newline.
104	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
105		var buf bytes.Buffer
106		enc := json.NewEncoder(&buf)
107		enc.SetIndent("", "  ")
108		enc.SetEscapeHTML(false)
109		if err := enc.Encode(snap); err != nil {
110			return nil, err
111		}
112		return buf.Bytes(), nil
113	}
114	
115	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
116	// can distinguish "field absent" from "field present with a zero value"
117	// (e.g. a missing formatVersion must be rejected rather than read as 0).
118	type rawSnapshot struct {
119		FormatVersion json.RawMessage `json:"formatVersion"`
120		ContentID     json.RawMessage `json:"contentId"`
121		Graph         json.RawMessage `json:"graph"`
122	}
123	
124	// isJSONNull reports whether a raw JSON value is the literal null.
125	func isJSONNull(raw json.RawMessage) bool {
126		return string(bytes.TrimSpace(raw)) == "null"
127	}
128	
129	// ParseSnapshot parses and strictly validates one snapshot document: required
130	// fields must be present and well-typed, no known field may be declared twice
131	// within the same object (even with identical values, a null first, or a
132	// spelling equivalent under Unicode case folding or JSON escaping), the
133	// format version must be supported, the embedded graph must be structurally
134	// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
135	// and the content identifier must correspond exactly to the graph. A
136	// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
137	// can never be trusted as a version.
138	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
139		if err := checkDuplicateFields(data); err != nil {
140			return nil, err
141		}
142		var raw rawSnapshot
143		if err := json.Unmarshal(data, &raw); err != nil {
144			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
145		}
146		if len(raw.FormatVersion) == 0 {
147			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
148		}
149		if len(raw.ContentID) == 0 {
150			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
151		}
152		if len(raw.Graph) == 0 {
153			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
154		}
155		// An explicit JSON null is present-but-untyped and must not be silently
156		// treated as a zero value (in particular, graph:null must not read as an
157		// empty graph).
158		if isJSONNull(raw.FormatVersion) {
159			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
160		}
161		if isJSONNull(raw.ContentID) {
162			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
163		}
164		if isJSONNull(raw.Graph) {
165			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
166		}
167	
168		var version int
169		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
170			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
171		}
172		if version != SnapshotFormatVersion {
173			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
174		}
175	
176		var contentID string
177		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
178			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
179		}
180		if contentID == "" {
181			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
182		}
183	
184		var gf GraphFile
185		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
186			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
187		}
188		// The embedded graph obeys exactly the same structural rules as a
189		// standalone graph file, so the two readers can never judge one graph
190		// differently.
191		adj, err := validateGraphStructureFromFile(gf.Datasets)
192		if err != nil {
193			return nil, err
194		}
195	
196		canonical, err := canonicalGraph(adj)
197		if err != nil {
198			return nil, err
199		}
200		if want := computeContentID(canonical); contentID != want {
201			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
202		}
203	
204		return &SnapshotFile{
205			FormatVersion: version,
206			ContentID:     contentID,
207			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
208		}, nil
209	}
210	
211	// checkDuplicateFields applies the shared repeated-known-field rule (see
212	// duplicate_fields.go) to a snapshot, supplying the snapshot's own field
213	// scope and locations: formatVersion, contentId, and graph at the top level,
214	// datasets inside graph, and name and upstreams inside each dataset record.
215	// The embedded graph is scanned by the same checkGraphObject a standalone
216	// graph file uses, so the two readers can never judge one graph differently.
217	func checkDuplicateFields(data []byte) error {
218		return runFieldScan(data, func(dec *json.Decoder) error {
219			return checkObjectFields(dec, "at the top level of the snapshot", []knownField{
220				{name: "formatVersion"},
221				{name: "contentId"},
222				{name: "graph", nested: func(dec *json.Decoder) error {
223					return checkGraphObject(dec, `in "graph"`)
224				}},
225			})
226		})
227	}
228	
229	// CompareSnapshots returns the fixed-direction diff from old to new. Both
230	// inputs are assumed to have passed ParseSnapshot; the report is fully
231	// deterministic and identical for semantically identical comparisons.
232	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
233		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
234		newAdj := adjacencyFromValidFile(newSnap.Graph)
235	
236		added, removed := diffRelations(oldAdj, newAdj)
237	
238		var newNodes, removedNodes, changedNodes []string
239		for name := range newAdj {
240			if oldParents, ok := oldAdj[name]; !ok {
241				newNodes = append(newNodes, name)
242			} else if !stringSliceEqual(oldParents, newAdj[name]) {
243				changedNodes = append(changedNodes, name)
244			}
245		}
246		for name := range oldAdj {
247			if _, ok := newAdj[name]; !ok {
248				removedNodes = append(removedNodes, name)
249			}
250		}
251		sort.Strings(newNodes)
252		sort.Strings(removedNodes)
253		sort.Strings(changedNodes)
254	
255		common := make([]string, 0)
256		for name := range oldAdj {
257			if _, ok := newAdj[name]; ok {
258				common = append(common, name)
259			}
260		}
261		sort.Strings(common)
262	
263		rootChanges := make([]RootSourceChange, 0)
264		for _, name := range common {
265			oldRoots := rootSources(name, oldAdj)
266			newRoots := rootSources(name, newAdj)
267			if !stringSliceEqual(oldRoots, newRoots) {
268				rootChanges = append(rootChanges, RootSourceChange{
269					Dataset:  name,
270					OldRoots: oldRoots,
271					NewRoots: newRoots,
272				})
273			}
274		}
275	
276		return &CompareReport{
277			NewDatasets:       orEmptyStrings(newNodes),
278			RemovedDatasets:   orEmptyStrings(removedNodes),
279			ChangedDatasets:   orEmptyStrings(changedNodes),
280			AddedRelations:    orEmptyRelations(added),
281			RemovedRelations:  orEmptyRelations(removed),
282			RootSourceChanges: rootChanges,
283		}
284	}
285	
286	// adjacencyFromValidFile builds normalized parent adjacency from an already
287	// validated graph file.
288	func adjacencyFromValidFile(gf GraphFile) adjacency {
289		adj := make(adjacency, len(gf.Datasets))
290		for _, ds := range gf.Datasets {
291			adj[ds.Name] = uniqueSorted(ds.Upstreams)
292		}
293		return adj
294	}
295	
296	// rootSources returns the root datasets reachable from node by following
297	// direct upstream edges. A node without upstreams is itself a root and its own
298	// source, so it is included. Nodes reached by more than one path count once.
299	// The result is sorted by name and never nil.
300	func rootSources(node string, adj adjacency) []string {
301		visited := make(map[string]bool)
302		var roots []string
303		var walk func(string)
304		walk = func(current string) {
305			if visited[current] {
306				return
307			}
308			visited[current] = true
309			parents := adj[current]
310			if len(parents) == 0 {
311				roots = append(roots, current)
312				return
313			}
314			for _, parent := range parents {
315				walk(parent)
316			}
317		}
318		walk(node)
319		sort.Strings(roots)
320		return orEmptyStrings(roots)
321	}
322	
323	func orEmptyStrings(s []string) []string {
324		if s == nil {
325			return []string{}
326		}
327		return s
328	}
329	
330	func orEmptyRelations(r []Relation) []Relation {
331		if r == nil {
332			return []Relation{}
333		}
334		return r
335	}
