1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8	)
9	
10	// PlanChange is one record in a lineage adjustment plan: the dataset name and
11	// the complete list of its direct upstreams after the batch is applied.
12	//
13	// A change may name a dataset that does not exist yet (it is registered) or an
14	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
15	// mentioned in the plan keep their current direct upstreams.
16	type PlanChange struct {
17		Name      string   `json:"name"`
18		Upstreams []string `json:"upstreams"`
19	}
20	
21	// Plan is a batch of lineage adjustments read from a JSON file.
22	//
23	// Removals names datasets that must be absent from the final graph. Deleting a
24	// name that does not currently exist is a no-op (it is not reported as an
25	// actual removal), so a successful plan can be applied again with empty change
26	// and impact lists. A name listed in Removals must not also appear in Changes.
27	type Plan struct {
28		Changes  []PlanChange `json:"changes"`
29		Removals []string     `json:"removals"`
30	}
31	
32	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
33	// downstream dataset derives from the upstream dataset.
34	type Relation struct {
35		Upstream   string `json:"upstream"`
36		Downstream string `json:"downstream"`
37	}
38	
39	// GraphDataset is one dataset record in the on-disk graph JSON.
40	type GraphDataset struct {
41		Name      string   `json:"name"`
42		Upstreams []string `json:"upstreams"`
43	}
44	
45	// GraphFile is the on-disk JSON representation of a lineage graph.
46	type GraphFile struct {
47		Datasets []GraphDataset `json:"datasets"`
48	}
49	
50	// BatchReport is the deterministic report produced by preview and apply.
51	//
52	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
53	// lists are sorted by name byte order; relation lists are sorted by upstream
54	// then downstream.
55	type BatchReport struct {
56		FinalGraph          GraphFile  `json:"finalGraph"`
57		NewDatasets         []string   `json:"newDatasets"`
58		ChangedDatasets     []string   `json:"changedDatasets"`
59		RemovedDatasets     []string   `json:"removedDatasets"`
60		AddedRelations      []Relation `json:"addedRelations"`
61		RemovedRelations    []Relation `json:"removedRelations"`
62		AffectedDownstreams []string   `json:"affectedDownstreams"`
63	}
64	
65	// graphAdjacency derives the normalized parent map from the in-memory graph.
66	// It rejects nil lineage nodes, empty names, and references to upstreams that
67	// are not registered; the name/reference rules are the shared ones from
68	// normalizeDatasets and validateAdjacencyReferences, also used by the file and
69	// snapshot readers. It does not check for cycles; use validateAcyclic for that.
70	func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
71		if graph == nil {
72			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
73		}
74		records := make([]GraphDataset, 0, len(graph))
75		for name, entry := range graph {
76			if entry == nil {
77				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
78			}
79			if name == "" {
80				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
81			}
82			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
83		}
84		adj, err := normalizeDatasets(records)
85		if err != nil {
86			return nil, err
87		}
88		if err := validateAdjacencyReferences(adj); err != nil {
89			return nil, err
90		}
91		return adj, nil
92	}
93	
94	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
95	// empty names, missing upstreams, and cycles. It does not mutate the graph.
96	//
97	// A graph that fails validation cannot be used as the basis for a batch: an
98	// adjustment plan must not be allowed to paper over pre-existing corruption.
99	func ValidateGraph(graph map[string]*Lineage) error {
100		adj, err := graphAdjacency(graph)
101		if err != nil {
102			return err
103		}
104		return validateAcyclic(adj)
105	}
106	
107	// computeBatch validates the graph and plan, then computes the final adjacency
108	// and the diff report. It does not mutate graph. The returned adjacency is the
109	// graph as it will be after the batch; callers that want to commit it should
110	// pass it to applyAdjacency.
111	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
112		if err := ValidateGraph(graph); err != nil {
113			return nil, nil, err
114		}
115		original, err := graphAdjacency(graph)
116		if err != nil {
117			return nil, nil, err
118		}
119	
120		// Validate the plan: empty names and duplicate declarations reject the
121		// whole batch, naming the dataset and the reason.
122		declarations := make(map[string]int, len(plan.Changes))
123		for _, change := range plan.Changes {
124			if change.Name == "" {
125				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
126			}
127			declarations[change.Name]++
128			if declarations[change.Name] > 1 {
129				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
130			}
131		}
132	
133		// Validate removals: empty names, duplicate names, and names also declared
134		// as changes all reject the whole batch with the name and reason.
135		removalDecls := make(map[string]int, len(plan.Removals))
136		for _, name := range plan.Removals {
137			if name == "" {
138				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
139			}
140			removalDecls[name]++
141			if removalDecls[name] > 1 {
142				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
143			}
144			if _, ok := declarations[name]; ok {
145				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
146			}
147		}
148	
149		// Build the final adjacency: start from the original parents, replace each
150		// planned dataset's parents with its normalized upstreams.
151		final := make(adjacency, len(original)+len(plan.Changes))
152		for name, parents := range original {
153			final[name] = append([]string(nil), parents...)
154		}
155		for name := range removalDecls {
156			delete(final, name)
157		}
158		var newNames []string
159		var changedNames []string
160		for _, change := range plan.Changes {
161			wanted := uniqueSorted(change.Upstreams)
162			old, existed := original[change.Name]
163			switch {
164			case !existed:
165				newNames = append(newNames, change.Name)
166			case !stringSliceEqual(old, wanted):
167				changedNames = append(changedNames, change.Name)
168			}
169			final[change.Name] = wanted
170		}
171		sort.Strings(newNames)
172		sort.Strings(changedNames)
173	
174		// Datasets actually removed: names in removals that existed in the
175		// original graph. Deleting a name that does not exist is a no-op and is
176		// not reported, so a successful plan can be applied again with empty lists.
177		var removedNames []string
178		for name := range removalDecls {
179			if _, existed := original[name]; existed {
180				removedNames = append(removedNames, name)
181			}
182		}
183		sort.Strings(removedNames)
184	
185		// Every upstream must resolve to a dataset that exists in the FINAL graph
186		// (new datasets may reference each other regardless of plan order; a
187		// retained dataset that still references a deleted name is rejected here,
188		// with both the referrer and the referenced name in the error). Iterate
189		// over sorted names so the reported pair is deterministic.
190		names := make([]string, 0, len(final))
191		for name := range final {
192			names = append(names, name)
193		}
194		sort.Strings(names)
195		for _, name := range names {
196			for _, parent := range final[name] {
197				if _, ok := final[parent]; !ok {
198					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
199				}
200			}
201		}
202		// The final graph must be acyclic, judged after all replacements.
203		if err := validateAcyclic(final); err != nil {
204			return nil, nil, err
205		}
206	
207		added, removed := diffRelations(original, final)
208		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
209	
210		report := &BatchReport{
211			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
212			NewDatasets:         newNames,
213			ChangedDatasets:     changedNames,
214			RemovedDatasets:     removedNames,
215			AddedRelations:      added,
216			RemovedRelations:    removed,
217			AffectedDownstreams: affected,
218		}
219		// Guarantee non-nil slices so JSON encodes empty lists as [].
220		if report.NewDatasets == nil {
221			report.NewDatasets = []string{}
222		}
223		if report.ChangedDatasets == nil {
224			report.ChangedDatasets = []string{}
225		}
226		if report.RemovedDatasets == nil {
227			report.RemovedDatasets = []string{}
228		}
229		if report.AddedRelations == nil {
230			report.AddedRelations = []Relation{}
231		}
232		if report.RemovedRelations == nil {
233			report.RemovedRelations = []Relation{}
234		}
235		if report.AffectedDownstreams == nil {
236			report.AffectedDownstreams = []string{}
237		}
238		return report, final, nil
239	}
240	
241	// PreviewBatch validates the graph and plan and returns the report WITHOUT
242	// mutating graph. Preview and apply for the same graph and plan produce
243	// identical reports.
244	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
245		report, _, err := computeBatch(graph, plan)
246		return report, err
247	}
248	
249	// ApplyBatch validates the plan, applies it to graph, and returns the report.
250	// On rejection, graph is left completely unchanged.
251	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
252		report, final, err := computeBatch(graph, plan)
253		if err != nil {
254			return nil, err
255		}
256		applyAdjacency(graph, final)
257		return report, nil
258	}
259	
260	// applyAdjacency rewrites the in-memory graph to match the final adjacency:
261	// nodes absent from final are removed, parents are replaced, and children are
262	// rebuilt from the parent edges.
263	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
264		for name := range graph {
265			if _, ok := final[name]; !ok {
266				delete(graph, name)
267			}
268		}
269		for name, parents := range final {
270			entry := graph[name]
271			if entry == nil {
272				entry = &Lineage{}
273				graph[name] = entry
274			}
275			entry.Dataset = name
276			entry.Parents = append([]string(nil), parents...)
277			entry.Children = nil
278		}
279		for name, parents := range final {
280			for _, parent := range parents {
281				graph[parent].Children = append(graph[parent].Children, name)
282			}
283		}
284		for name := range graph {
285			graph[name].Children = uniqueSorted(graph[name].Children)
286		}
287	}
288	
289	// diffRelations returns the directed edges present in final but not original
290	// (added) and present in original but not final (removed). Both lists are
291	// sorted by upstream then downstream.
292	func diffRelations(original, final adjacency) (added, removed []Relation) {
293		origEdges := edgeSet(original)
294		finalEdges := edgeSet(final)
295		for e := range finalEdges {
296			if !origEdges[e] {
297				added = append(added, e)
298			}
299		}
300		for e := range origEdges {
301			if !finalEdges[e] {
302				removed = append(removed, e)
303			}
304		}
305		sortRelations(added)
306		sortRelations(removed)
307		return added, removed
308	}
309	
310	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
311	func edgeSet(adj adjacency) map[Relation]bool {
312		set := make(map[Relation]bool)
313		for downstream, parents := range adj {
314			for _, upstream := range parents {
315				set[Relation{Upstream: upstream, Downstream: downstream}] = true
316			}
317		}
318		return set
319	}
320	
321	// sortRelations sorts by upstream then downstream.
322	func sortRelations(rels []Relation) {
323		sort.Slice(rels, func(i, j int) bool {
324			if rels[i].Upstream != rels[j].Upstream {
325				return rels[i].Upstream < rels[j].Upstream
326			}
327			return rels[i].Downstream < rels[j].Downstream
328		})
329	}
330	
331	// affectedDownstreams computes the impact set: starting from the seed datasets
332	// (new, actually changed, or actually removed), follow downstream (children)
333	// edges in BOTH the original and the final graphs. Datasets that are
334	// themselves seeds are excluded from the output; every other reachable dataset
335	// is included once.
336	//
337	// Walking both graphs matters when relations are deleted: a dataset that was
338	// reachable downstream before the change (and thus loses a lineage path) is
339	// still affected even if the edge is gone in the final graph. Removed datasets
340	// are seeds too, so a downstream that lost its upstream node is counted.
341	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
342		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
343		for _, name := range newNames {
344			seeds[name] = true
345		}
346		for _, name := range changedNames {
347			seeds[name] = true
348		}
349		for _, name := range removedNames {
350			seeds[name] = true
351		}
352	
353		origChildren := invertAdjacency(original)
354		finalChildren := invertAdjacency(final)
355	
356		seen := make(map[string]bool)
357		queue := make([]string, 0, len(seeds))
358		for seed := range seeds {
359			queue = append(queue, seed)
360		}
361		for len(queue) > 0 {
362			node := queue[0]
363			queue = queue[1:]
364			for _, child := range origChildren[node] {
365				if !seen[child] {
366					seen[child] = true
367					queue = append(queue, child)
368				}
369			}
370			for _, child := range finalChildren[node] {
371				if !seen[child] {
372					seen[child] = true
373					queue = append(queue, child)
374				}
375			}
376		}
377	
378		out := make([]string, 0, len(seen))
379		for name := range seen {
380			if !seeds[name] {
381				out = append(out, name)
382			}
383		}
384		sort.Strings(out)
385		return out
386	}
387	
388	// invertAdjacency maps each dataset to the datasets that depend on it (its
389	// children), with each child list sorted by name.
390	func invertAdjacency(adj adjacency) map[string][]string {
391		children := make(map[string][]string, len(adj))
392		for name, parents := range adj {
393			for _, parent := range parents {
394				children[parent] = append(children[parent], name)
395			}
396		}
397		for name := range children {
398			sort.Strings(children[name])
399		}
400		return children
401	}
402	
403	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
404	// records with non-nil upstream lists.
405	func adjacencyToDatasets(adj adjacency) []GraphDataset {
406		names := make([]string, 0, len(adj))
407		for name := range adj {
408			names = append(names, name)
409		}
410		sort.Strings(names)
411		ds := make([]GraphDataset, 0, len(names))
412		for _, name := range names {
413			parents := adj[name]
414			if parents == nil {
415				parents = []string{}
416			}
417			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
418		}
419		return ds
420	}
421	
422	// stringSliceEqual reports whether a and b contain the same strings in the
423	// same order. Both are expected to be sorted and duplicate-free.
424	func stringSliceEqual(a, b []string) bool {
425		if len(a) != len(b) {
426			return false
427		}
428		for i := range a {
429			if a[i] != b[i] {
430				return false
431			}
432		}
433		return true
434	}
435	
436	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
437	// The graph must satisfy every structure rule a reader enforces; nil nodes,
438	// empty names, missing upstreams, and dependency cycles (including a dataset
439	// that lists itself) reject the export with no bytes returned, so a successful
440	// result can always be read back with UnmarshalGraphFile. The check is
441	// read-only: the in-memory graph is never modified.
442	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
443		adj, err := graphAdjacency(graph)
444		if err != nil {
445			return nil, err
446		}
447		if err := validateAcyclic(adj); err != nil {
448			return nil, err
449		}
450		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
451		return json.MarshalIndent(gf, "", "  ")
452	}
453	
454	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
455	// graph (parents and derived children). The graph is checked with the same
456	// structural rules a snapshot enforces (empty names, duplicate datasets,
457	// missing upstreams, and cycles); a structurally invalid graph is rejected so
458	// it cannot be used as the basis for a batch. As in a snapshot, a known field
459	// declared twice within the same object — datasets in the graph object, name
460	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
461	// even when the duplicates carry identical values.
462	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
463		if err := checkGraphFileDuplicateFields(data); err != nil {
464			return nil, err
465		}
466		var gf GraphFile
467		if err := json.Unmarshal(data, &gf); err != nil {
468			return nil, fmt.Errorf("invalid graph JSON: %w", err)
469		}
470		adj, err := validateGraphStructureFromFile(gf.Datasets)
471		if err != nil {
472			return nil, err
473		}
474		// Rebuild children from the parent edges so the in-memory graph is
475		// consistent regardless of how the file was produced.
476		return lineageFromAdjacency(adj), nil
477	}
478	
479	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
480	// duplicate declarations) is validated later by computeBatch so that preview
481	// and apply share identical rejection behavior.
482	//
483	// A known field declared twice within the same object — changes or removals
484	// at the top level, name or upstreams inside one change record — is
485	// ambiguous: the reader would silently keep only the last declaration and
486	// drop the earlier adjustment. The whole plan is refused instead, even when
487	// the duplicates carry identical values, one is null, or the surviving value
488	// is a legal empty list. Field names are recognized the same way the decoder
489	// resolves them (after JSON unescaping, with Unicode case folding), so a
490	// second declaration spelled "Changes" or "changes" still collides;
491	// dataset names themselves stay case-sensitive. Unknown fields keep their
492	// ignore-everything behavior and may repeat freely.
493	func UnmarshalPlan(data []byte) (Plan, error) {
494		var p Plan
495		if err := checkPlanDuplicateFields(data); err != nil {
496			return p, err
497		}
498		if err := json.Unmarshal(data, &p); err != nil {
499			return p, fmt.Errorf("invalid plan JSON: %w", err)
500		}
501		return p, nil
502	}
503	
504	// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
505	// (see duplicate_fields.go) to a standalone graph file, supplying the graph
506	// file's own location: datasets may be declared only once in the top-level
507	// graph object, and name and upstreams only once in each dataset record. The
