11	// cyclicGraph builds an in-memory graph with the given parent lists by hand.
12	// Register itself can never produce a cycle, so cycle fixtures must bypass it.
13	// Parent lists are stored verbatim (unsorted, with duplicates kept), which
14	// lets tests prove the export leaves the caller's lists untouched.
15	func cyclicGraph(t *testing.T, parents map[string][]string) map[string]*Lineage {
16		t.Helper()
17		graph := make(map[string]*Lineage, len(parents))
18		for name, ups := range parents {
19			graph[name] = &Lineage{Dataset: name, Parents: ups}
20		}
21		for name, entry := range graph {
22			for _, parent := range entry.Parents {
23				if p := graph[parent]; p != nil {
24					p.Children = append(p.Children, name)
25				}
26			}
27		}
28		return graph
29	}
30	
31	// cloneGraph returns a deep, value-equal copy of graph for before/after checks.
32	func cloneGraph(graph map[string]*Lineage) map[string]*Lineage {
33		out := make(map[string]*Lineage, len(graph))
34		for name, entry := range graph {
35			if entry == nil {
36				out[name] = nil
37				continue
38			}
39			cp := &Lineage{Dataset: entry.Dataset}
40			cp.Parents = append([]string(nil), entry.Parents...)
41			cp.Children = append([]string(nil), entry.Children...)
42			out[name] = cp
43		}
44		return out
45	}
